def evaluate_P(x, y, z):
    """
    Evaluates P = y^x z^y x^z.
    Returns P if it's a positive integer, otherwise returns None.
    Handles edge cases for exponentiation.
    """
    try:
        # y^x
        try:
            term1 = y**x
        except OverflowError:
            return None # Too large
        except ValueError:
            # This typically happens if y < 0 and x is not an integer, but x is an integer here.
            # However, Python handles integer exponents fine. If y=0 and x<0, it raises ZeroDivisionError.
            if y == 0 and x < 0:
                return None # Not an integer
            raise

        # z^y
        try:
            term2 = z**y
        except OverflowError:
            return None
        except ValueError:
            if z == 0 and y < 0:
                return None # Not an integer
            raise

        # x^z
        try:
            term3 = x**z
        except OverflowError:
            return None
        except ValueError:
            if x == 0 and z < 0:
                return None # Not an integer
            raise

        P = term1 * term2 * term3
        return P
    except Exception:
        return None

